  // за горния алгоритъм разместването е ДВЕ разлики, значи пропуск.
  function разместено(a, b) {
    if (a.length !== b.length) return false;
    const d = [];
    for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) { d.push(i); if (d.length > 2) return false; }
    return d.length === 2 && d[1] === d[0] + 1 && a[d[0]] === b[d[1]] && a[d[1]] === b[d[0]];
  }
  // 🔴 19.08 (корпус 350) — КОЛКО ТЕЖИ ПРОСТЕНАТА ДУМА.
  //   Простеното попадение струваше 1.5, а прагът за отговор е 2. Разликата
  //   я покриваше само множителят за СВОЯ стая (×1.6 → 2.4). Тоест: сбъркаш
  //   ли буква в дума, чиято карта живее в ДРУГА стая, получаваш тишина.
  //   Измерено: „какво значи висок хемогллобин" (едно удвоено „л") →
