  // ── ✂️ СЛЕТИТЕ ДУМИ ──
  // 🔴 19.08 (корпус 350, ИЗМЕРЕНО): майка пише с една ръка и интервалът пада.
  //   Четири въпроса получаваха „не знам", защото са ЕДНА дума:
  //     „неискадасучеотляватагърда"        (mb-otkaz-gyrda СЪЩЕСТВУВА)
  //     „болигоушенцетоиседърпа"           (zd-ear СЪЩЕСТВУВА)
  //     „когапрохождаобикновено"           (rz-prohojdane СЪЩЕСТВУВА)
  //     „къдедавидякалендаранапрегледите"  (br-pregledi СЪЩЕСТВУВА)
  //   Речникът се прави от САМАТА база (ключове + заглавия) — не се измисля.
  //   ⚠ ТРИТЕ СПИРАЧКИ, за да не се цепи истинска дълга дума:
  //     1. под 14 букви изобщо не се пробва („прохождането" е 12);
  //     2. ако цялата дума е в речника, остава цяла;
