  // 🔵 УВЕРЕНОСТТА НА ТЕКУЩОТО ПОПАДЕНИЕ (виж дългия коментар долу в findEntry).
  //   Живее ЕДИН ход: всяко извикване на findEntry я нулира и я презаписва.
