          //    седем точки за една-единствена написана дума „майка“ и биеше
          //    точното тридточково съвпадение. Реален резултат: „сама майка съм“
          //    отиваше при „Майка ми и аз, отначало“, а „няма ме на нито една
          //    снимка“ — при „Сама съм“ (четири ключа с „няма“). Тоест записът
